const v3TextOriginals=new WeakMap(),v3AttrOriginals=new WeakMap();let v3LocaleObserver=null;
function v3translateText(source){let raw=String(source||''),trim=raw.trim(),dict=v3Lang==='en'?v3En:v3Vi,out=dict[trim];if(out===undefined){out=trim;for(let key of Object.keys(dict).filter(k=>k.length>4).sort((a,b)=>b.length-a.length)){if(out.includes(key))out=out.split(key).join(dict[key])}if(v3Lang==='en'){out=out.replace(/(\d+) bàn trong/g,'$1 tables in').replace(/Gaming date/g,'Gaming Date')}else{out=out.replace(/(\d+) tables in/g,'$1 bàn trong').replace(/Top 10 Win/g,'Top 10 Thắng').replace(/Top 10 Loss/g,'Top 10 Thua').replace(/Gaming date/g,'Ngày gaming')}}return raw.replace(trim,out)}
function v3applyLanguage(root){if(!root)return;let walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);while(walker.nextNode()){let node=walker.currentNode;if(!v3TextOriginals.has(node))v3TextOriginals.set(node,node.nodeValue);let original=v3TextOriginals.get(node),value=v3Lang==='vi'?v3translateText(original):v3translateText(original);if(node.nodeValue!==value)node.nodeValue=value}let elements=root.querySelectorAll('*');for(let el of elements){let attrs=['placeholder','title','aria-label'];for(let attr of attrs)if(el.hasAttribute(attr)){let map=v3AttrOriginals.get(el);if(!map){map={};v3AttrOriginals.set(el,map)}if(map[attr]===undefined)map[attr]=el.getAttribute(attr);let original=map[attr],value=v3translateText(original);if(el.getAttribute(attr)!==value)el.setAttribute(attr,value)}}}
function v3setLanguage(lang){v3Lang=lang==='en'?'en':'vi';localStorage.setItem('grandht_ops_language',v3Lang);document.querySelectorAll('#languageChoices button').forEach(b=>b.classList.toggle('active',b.dataset.lang===v3Lang));v3applyLanguage(document.body)}
function v3watchLanguage(){document.querySelectorAll('#languageChoices button').forEach(b=>b.classList.toggle('active',b.dataset.lang===v3Lang));v3applyLanguage(document.body);if(v3LocaleObserver)v3LocaleObserver.disconnect();v3LocaleObserver=new MutationObserver(records=>{for(let r of records){if(r.type==='childList'){for(let n of r.addedNodes){if(n.nodeType===Node.ELEMENT_NODE)v3applyLanguage(n);else if(n.nodeType===Node.TEXT_NODE){if(!v3TextOriginals.has(n))v3TextOriginals.set(n,n.nodeValue);let value=v3translateText(v3TextOriginals.get(n));if(n.nodeValue!==value)n.nodeValue=value}}}else if(r.type==='characterData'){let n=r.target;if(!v3TextOriginals.has(n))v3TextOriginals.set(n,n.nodeValue);let value=v3translateText(v3TextOriginals.get(n));if(n.nodeValue!==value)n.nodeValue=value}else if(r.type==='attributes')v3applyLanguage(r.target)}});v3LocaleObserver.observe(document.body,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:['placeholder','title','aria-label']})}
function v3cash(n){let v=Number(n||0),unit=cfg.currency||'C$';if(unit==='HKD')v/=Number(cfg.cPerHKD||3375);else if(unit==='USD')v/=Number(cfg.cPerUSD||27000);else if(unit==='VND')v*=Number(cfg.cPerVND||1000);let digits=unit==='C$'||unit==='VND'?0:2;return `${v<0?'-':''}${unit}${Math.abs(v).toLocaleString('en-US',{minimumFractionDigits:0,maximumFractionDigits:digits})}`}
function v3tableRows(date){let base=state.tables.filter(x=>x.date===date).map(x=>({...x,pit:x.pit||pitNum(x.code),area:areaOfRecord(x.code,date,`Pit ${x.pit||''}`)}));return [...new Map(base.map(x=>[`${x.date}|${x.code}|${x.shift||x.source}`,x])).values()]}
function v3playerRows(date){let base=state.players.filter(x=>x.date===date).map(x=>({...x,playerId:x.playerId||x.id||'',pit:x.pit||pitNum(x.table),area:areaOfRecord(x.table,date,`Pit ${x.pit||''}`)}));return [...new Map(base.map(x=>[`${x.date}|${x.playerId||x.player}|${x.ratingId||`${x.table}|${x.played}`}`,x])).values()]}
function v3commissionKey(program){let m=String(program||'').toUpperCase().match(/(\d+(?:\.\d+)?\s*[KMB])\s*$/);return m?m[1].replace(/\s/g,''):''}
function v3rateForProgram(program){let key=v3commissionKey(program);return key&&Number.isFinite(Number(cfg.dvipRates[key]))?Number(cfg.dvipRates[key]):Number(cfg.commissionPct||0)}
function v3nameKey(name){return String(name||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/gi,'').toUpperCase()}
function dealerOfMGM(row,date){let type=String(row.program||'').toUpperCase(),pid=String(row.playerId||''),detail=String(row.detailId||''),nameKey=v3nameKey(row.player),rating=(state.players||[]).find(x=>x.date===date&&String(x.playerId||x.id||'')===pid),mapped=(cfg.agents||[]).find(x=>{if(x.playerId&&String(x.playerId)!==pid)return false;if(x.detailId&&String(x.detailId)!==detail)return false;if(x.playerId)return true;return !!x.playerName&&v3nameKey(x.playerName)===nameKey}),pit=rating?.pit||pitNum(rating?.table||'');let ratedArea=rating?areaOfRecord(rating.table,date,`Pit ${pit||''}`):'';if(type.includes('PDP'))return {area:'DVIP',dealer:row.player||'DVIP',pit,table:rating?.table||'',commissionRate:v3rateForProgram(row.program),commissionKey:v3commissionKey(row.program)};if(type.replace(/[^A-Z0-9]/g,'').includes('FIXEDITO'))return {area:mapped?.area||'ITO',dealer:mapped?.dealer||row.player||'ITO',pit,table:rating?.table||'',commissionRate:0,commissionKey:''};if(mapped)return {area:mapped.area,dealer:mapped.dealer||row.player,pit,table:rating?.table||'',commissionRate:0,commissionKey:''};if(rating)return {area:ratedArea,dealer:`Player ${pid}`,pit,table:rating.table||'',commissionRate:0,commissionKey:''};return {area:'Unmapped',dealer:row.player||`Player ${pid}`,pit,table:'',commissionRate:0,commissionKey:''}}
function v3rollingRows(date){let base=(mgmRows||[]).filter(x=>x.date===date).map(x=>{let meta=dealerOfMGM(x,date),rolling=Number(x.purchase||0)+Number(x.exchange||0)-Number(x.returned||0),recordedCommission=Number(x.commission||0);return {...x,...meta,rolling,commission:recordedCommission||(meta.area==='DVIP'?rolling*meta.commissionRate/100:0)}});return [...new Map(base.map(x=>[x.documentId?`${date}|${x.documentId}`:`${date}|${x.playerId}|${x.program}|${x.purchase}|${x.exchange}|${x.returned}`,x])).values()]}
function v3pitLabel(n){let value=Number(n);return `Pit ${Number.isFinite(value)&&value>0?String(value).padStart(2,'0'):'—'}`}
function v3areaOptions(){return [...new Set([...(cfg.pits||[]).map(x=>x.area),...(cfg.agents||[]).map(x=>x.area),...(state.tables||[]).map(x=>areaOfRecord(x.code,x.date,`Pit ${x.pit||''}`)),...(state.players||[]).map(x=>areaOfRecord(x.table,x.date,`Pit ${x.pit||''}`)),...(mgmRows||[]).map(x=>dealerOfMGM(x,x.date).area),'ITO','DVIP','House','Unmapped'])].filter(Boolean).sort()}
function v3dates(){return [...new Set([...state.tables,...state.players,...(mgmRows||[])].map(x=>x.date).filter(Boolean))].sort()}
