 v3Root.innerHTML=`<header class="v3top"><div class="v3brand"><div class="v3logo" aria-label="Casino Smart Operation logo"><svg viewBox="0 0 32 32" aria-hidden="true"><path d="M16 25.5V17m0 4c-1.2 2.3-4.5 3-6.6.8-2.2-2.2-1.4-5.3 1.4-6.4-1.4-2.6-.4-5.1 1.8-5.9 1.5-.6 3.1.1 4 1.4 1-2 3.4-2.6 5.2-1.2 2 1.5 2.1 4.2.5 6.1 2.5 1.6 2.8 4.6.7 6.4-1.9 1.6-4.8 1.1-6-1.2Zm-3 7h6" fill="none" stroke="#08111f" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"/><circle cx="16" cy="16" r="1.35" fill="#08111f"/><path d="M24.8 7.2 27 5m-1 5 3-1" stroke="#fff1b8" stroke-width="1.5" stroke-linecap="round"/></svg></div><div><strong>CASINO SMART OPERATION</strong><small>LIVE REPORT</small></div></div><nav class="v3nav"><button data-page="overview">▤ Tổng quan Casino</button><button data-page="revenue">⌁ Doanh thu Casino</button><button data-page="rolling">◉ Rolling & ITO / DVIP</button><button data-page="rating">♙ Player Rating (Top 10)</button><button data-page="mapping">▦ Table Ownership</button></nav><div class="v3tools"><div class="v3langs" id="languageChoices"><button data-lang="vi" onclick="v3setLanguage('vi')">VI</button><button data-lang="en" onclick="v3setLanguage('en')">EN</button></div><div class="v3curr" id="currencyChoices"></div><input type="date" id="dateFilter"><button id="syncFolder">☁ Nạp File Sync</button><button id="settingsButton" title="Mapping & settings">⚙</button><button id="uploadButton">Import reports</button><div id="fileSlot" hidden></div></div></header><main class="v3main"><section class="v3title" id="viewTitle"></section><section class="v3kpis" id="viewKpis"></section><section id="viewFilters"></section><section id="viewContent"></section></main><footer class="v3foot"><span id="syncTag">Folder sync off</span><span>Source data: Shift Analysis · MGM NN Chip Purchase · Player Rating</span><span>© Copyright by Guy Nguyen</span></footer><div id="toast" class="toast"></div>`;
