 let filtered=v3filteredTables(tables),d=filtered.reduce((a,x)=>a+x.drop,0),w=filtered.reduce((a,x)=>a+x.result,0),pitCount=new Set(filtered.map(x=>x.pit)).size;document.getElementById('viewKpis').innerHTML=v3kpi(`Total Drop (${v3Area==='All areas'?'All':v3esc(v3Area)})`,v3cash(d))+v3kpi(`Casino Win/Loss (${v3Area==='All areas'?'All':v3esc(v3Area)})`,`${w>0?'+':''}${v3cash(w)}`,'green')+v3kpi('Hold Rate (%)',`${d?(w/d*100).toFixed(1):'0.0'}%`,'cyan')+v3kpi('Pits / Tables',`${pitCount} / ${filtered.length}`,'blue');
