 root.innerHTML=`<div class="v3tabs"><button class="${v3RatingMode==='win'?'on':''}" onclick="v3setRatingMode('win')">↗ Top 10 Win (${list.filter(x=>x.wl>0).length>10?10:list.filter(x=>x.wl>0).length})</button><button class="${v3RatingMode==='loss'?'on':''}" onclick="v3setRatingMode('loss')">↘ Top 10 Loss (${list.filter(x=>x.wl<0).length>10?10:list.filter(x=>x.wl<0).length})</button><button class="${v3RatingMode==='all'?'on':''}" onclick="v3setRatingMode('all')">Tất cả khách (${list.length})</button><span class="v3grow"></span><small>${data.length} khách · Gaming Date ${date||'—'}</small></div><div class="v3tablewrap"><table class="v3table"><thead><tr><th>#</th><th>Tên khách hàng</th><th>Player ID</th><th class="num">Khách thắng/thua</th><th class="num">Casino Win/Loss</th><th class="num">Total In</th><th class="num">Chips Out</th><th class="num">Avg Bet</th><th>Khu vực & Pit</th><th>Bàn chơi</th><th class="num">DVIP Rolling</th><th class="num">Commission %</th><th>Chi tiết</th></tr></thead><tbody>${data.map((x,i)=>`<tr><td><b class="rank">${i+1}</b></td><td><b>${v3esc(x.name)}</b><small>${x.records.length} rating slips</small></td><td class="tablecode">${v3esc(x.id)}</td><td class="num green">${x.wl>0?'+':''}${v3cash(x.wl)}</td><td class="num ${-x.wl<0?'red':'green'}">${v3cash(-x.wl)}</td><td class="num">${v3cash(x.totalIn)}</td><td class="num">${v3cash(x.chipsOut)}</td><td class="num gold">${v3cash(x.avg)}</td><td>${[...x.areas].map(v3esc).join(', ')}<small>${[...x.pits].join(', ')}</small></td><td class="codes">${[...x.tables].map(v3esc).join(', ')}</td><td class="num">${x.areas.has('DVIP')?v3cash(x.dvipRolling):'—'}</td><td class="num">${x.dvipRolling?x.dvipRate.toFixed(2)+'%':'—'}</td><td><button class="v3slips" onclick="v3showSlips(${JSON.stringify(x.id)})">Slips (${x.records.length})</button></td></tr>`).join('')||`<tr><td colspan="13" class="v3empty">Không có Player Rating cho ngày/khu vực này.</td></tr>`}</tbody></table></div>`;
