function v3enhanceMapping(){let root=document.getElementById('viewContent'),panel=root.querySelectorAll('.v3panel')[2];if(!panel)return;let form=panel.querySelector('form');form.innerHTML='<input id="v3playerName" placeholder="Player Name" required><input id="v3pid" placeholder="PlayerID" required><input id="v3detail" placeholder="Program Detail ID" required><input id="v3agentArea" placeholder="Area · ITO LW / ITO GD" required><button class="v3button primary">Lưu ITO mapping</button>';panel.querySelector('thead').innerHTML='<tr><th>Player Name</th><th>PlayerID</th><th>Program Detail ID</th><th>Mapped Area</th><th></th></tr>';panel.querySelector('tbody').innerHTML=cfg.agents.map((x,i)=>`<tr><td>${v3esc(x.playerName||x.dealer||'')}</td><td>${v3esc(x.playerId||'')}</td><td>${v3esc(x.detailId||'')}</td><td>${v3esc(x.area)}</td><td><button onclick="v3removeAgent(${i})">Xóa</button></td></tr>`).join('')||'<tr><td colspan="5" class="v3empty">Chưa có ITO player mapping.</td></tr>';panel.querySelector('.v3hint').textContent='PDP được phân vào DVIP. FIXED ITO được phân vào Area đã map theo Player Name + PlayerID + Program Detail ID.';let rates=Object.entries(cfg.dvipRates||{}).sort((a,b)=>parseFloat(a[0])-parseFloat(b[0]));root.insertAdjacentHTML('beforeend',`<section class="v3panel"><h2>DVIP Commission Mapping · Program Type suffix</h2><p class="v3hint">Hệ thống capture mức chip ở cuối Program Type (ví dụ PDP - 50K) và áp dụng tỷ lệ commission bên dưới.</p><form onsubmit="v3saveCommissionRates(event)"><div class="v3rategrid">${rates.map(([key,value])=>`<label>${v3esc(key)}<span><input class="dvip-rate" data-rate-key="${v3esc(key)}" type="number" min="0" step="0.01" value="${Number(value)}"> %</span></label>`).join('')}</div><div class="v3rateadd"><input id="v3newDenom" placeholder="New Program suffix · 1M"><input id="v3newRate" type="number" min="0" step="0.01" placeholder="Commission %"><button class="v3button primary">Save commission rates</button></div></form></section>`)}
function v3saveCommissionRates(e){e.preventDefault();for(let input of document.querySelectorAll('.dvip-rate'))cfg.dvipRates[input.dataset.rateKey]=Number(input.value)||0;let raw=document.getElementById('v3newDenom').value.trim();if(raw){let key=v3commissionKey(`PDP ${raw}`),rate=Number(document.getElementById('v3newRate').value);if(!key||!Number.isFinite(rate)){toast('Nhập hậu tố dạng 10K / 1M và commission rate');return}cfg.dvipRates[key]=rate}v2save();render()}
function v3bars(areas){let m=Math.max(1,...areas.map(([a,g])=>Math.max(g.rolling||0,Math.abs(g.result||0))));return `<div class="v3bars">${areas.map(([a,g])=>`<div class="v3barrow"><label>${v3esc(a)}</label><div class="v3barset"><span class="barrolling" style="width:${Math.max(1,(g.rolling||0)/m*100)}%"></span><small>${v3cash(g.rolling||0)}</small></div><div class="v3barset"><span class="barwin" style="width:${Math.max(1,Math.abs(g.result||0)/m*100)}%"></span><small>${v3cash(g.result||0)}</small></div></div>`).join('')}</div><div class="v3legend"><span>Rolling</span><span>Result</span></div>`}
function v3setRatingMode(m){v3RatingMode=m;v3renderContent()}
function v3selectArea(encoded){v3Area=decodeURIComponent(encoded);v3navigate('revenue')}
function v3showSlips(id){let date=document.getElementById('dateFilter').value,rows=v3playerRows(date).filter(x=>String(x.playerId)===String(id));let pop=document.createElement('div');pop.className='v3modal';pop.innerHTML=`<div><button class="close" onclick="this.closest('.v3modal').remove()">✕</button><h2>Rating slips · ${v3esc(id)}</h2><div class="v3tablewrap"><table class="v3table"><thead><tr><th>Date</th><th>Table</th><th>Avg Bet</th><th>Total In</th><th>Chips Out</th><th>Est. W/L</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${x.date}</td><td>${v3esc(x.table)}</td><td>${v3cash(x.avg)}</td><td>${v3cash(x.totalIn||x.buy)}</td><td>${v3cash(x.chipsOut)}</td><td>${v3cash(x.wl)}</td></tr>`).join('')}</tbody></table></div></div>`;document.body.appendChild(pop)}
function v3addPit(e){e.preventDefault();let raw=document.getElementById('v3pit').value.trim(),pit=Number(raw.match(/\d+/)?.[0]),area=document.getElementById('v3area').value.trim();if(!Number.isInteger(pit)||pit<1||!area){toast('Nhập Pit hợp lệ (ví dụ: 6 hoặc Pit 06) và tên khu vực');return}cfg.pits=cfg.pits.filter(x=>Number(x.pit)!==pit);cfg.pits.push({pit,area});cfg.pits.sort((a,b)=>a.pit-b.pit);v2save();render()}
function v3addTableOwner(e){e.preventDefault();let table=document.getElementById('v3tableCode').value.trim().toUpperCase(),owner=document.getElementById('v3owner').value,from=document.getElementById('v3from').value,to=document.getElementById('v3to').value;if(to&&to<from){toast('Ngày kết thúc phải sau ngày bắt đầu');return}if(state.mappings.some(x=>x.table===table&&from<=(x.to||'9999-12-31')&&(!to||to>=x.from))){toast('Ngày hiệu lực đang bị trùng cho mã bàn này');return}state.mappings.push({table,owner,from,to});state.mappings.sort((a,b)=>a.table.localeCompare(b.table)||a.from.localeCompare(b.from));v2save();render()}
function v3addAgent(e){e.preventDefault();let playerName=document.getElementById('v3playerName').value.trim(),playerId=document.getElementById('v3pid').value.trim(),detailId=document.getElementById('v3detail').value.trim(),area=document.getElementById('v3agentArea').value.trim();if(!playerName||!playerId||!detailId||!area){toast('Nhập Player Name, PlayerID, Program Detail ID và Area mapping');return}cfg.agents=cfg.agents.filter(x=>!(String(x.playerId)===playerId&&String(x.detailId)===detailId));cfg.agents.push({playerName,playerId,detailId,dealer:playerName,area});v2save();render()}
function v3removePit(i){cfg.pits.splice(i,1);v2save();render()}function v3removeTableOwner(i){state.mappings.splice(i,1);v2save();render()}function v3removeAgent(i){cfg.agents.splice(i,1);v2save();render()}
async function chooseFolder(){if(!window.showDirectoryPicker){document.getElementById('files').click();return}try{dirHandle=await window.showDirectoryPicker({mode:'read'});state.folder=dirHandle.name;v2save();document.getElementById('syncTag').innerHTML=`● Watching ${v3esc(dirHandle.name)}`;await scanFolder();if(!window.__casinoSyncTimer)window.__casinoSyncTimer=setInterval(scanFolder,20000)}catch(e){if(e.name!=='AbortError')toast('Không thể đọc thư mục đã chọn')}}
async function scanFolder(){if(!dirHandle)return;let foundNewFile=false;try{for await(let [name,handle] of dirHandle.entries()){if(handle.kind!=='file'||! /\.(csv|xlsx|xls)$/i.test(name))continue;let file=await handle.getFile(),sig=file.name+'|'+file.size+'|'+file.lastModified;if(!seen.has(sig)){foundNewFile=true;await importFiles([file])}}if(!v3DateWasUserSelected&&foundNewFile){let latest=v3dates().at(-1);if(latest)document.getElementById('dateFilter').value=latest}render()}catch(e){console.warn('Casino report folder scan',e)}}
function v3export(){let date=document.getElementById('dateFilter').value,headers=[],rows=[];if(v3Page==='revenue'){headers=['Gaming Date','Area','Pit','Table','Game','Drop','Result','Hold'];rows=v3filteredTables(v3tableRows(date)).map(x=>[x.date,x.area,v3pitLabel(x.pit),x.code,x.game,x.drop,x.result,x.drop?x.result/x.drop:0])}else if(v3Page==='rolling'){headers=['Gaming Date','Area','Pit','Dealer/Player','PlayerID','ProgramType','ChipPurchase','ChipExchange','ChipReturn','Rolling','Commission'];rows=v3filteredRolling(v3rollingRows(date)).map(x=>[x.date,x.area,x.pit||'',x.dealer||x.player,x.playerId,x.program,x.purchase,x.exchange,x.returned,x.rolling,x.commission])}else{headers=['Gaming Date','Player','PlayerID','Player W/L','Casino W/L','Total In','Chips Out','Avg Bet','Area','Table'];rows=v3filteredPlayers(v3playerRows(date)).map(x=>[x.date,x.player,x.playerId,x.wl,-x.wl,x.totalIn||x.buy,x.chipsOut,x.avg,x.area,x.table])}let csv=[headers,...rows].map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\r\n'),url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`casino-${v3Page}-${date||'all'}.csv`;a.click();URL.revokeObjectURL(url)}
Object.assign(v3Vi,{'Player Name':'Tên khách hàng','Player Win/Loss':'Khách thắng/thua','Area':'Khu vực','Commission %':'Commission %','Player Rating slips':'Lượt chơi Player Rating','MGM NN Chip Purchase':'MGM NN Chip Purchase','Rating slips':'Lượt rating','Total In':'Total In','Chips Out':'Chips Out','Avg Bet':'Avg Bet','Time Played':'Thời gian chơi','No rating slip.':'Không có rating slip.','No MGM transactions for this player.':'Khách này không có giao dịch MGM.','There are no customers in this area on the selected Gaming Date.':'Không có khách trong khu vực này ở Gaming Date đã chọn.'});
const v3renderContentBase=v3renderContent;
function v3playerRows(date){let shiftByTable=new Map((state.tables||[]).filter(t=>t.date===date).map(t=>[String(t.code||'').trim().toUpperCase(),t]));let base=state.players.filter(x=>x.date===date).map(x=>{let table=String(x.table||'').trim(),shift=shiftByTable.get(table.toUpperCase()),pit=pitNum(table,shift?.pitName)||pitNum(table)||pitNum(table,`Pit ${x.pit||''}`),area=areaOfRecord(table,date,`Pit ${pit||''}`);return {...x,playerId:x.playerId||x.id||'',pit,area}});return [...new Map(base.map(x=>[`${x.date}|${x.playerId||x.player}|${x.ratingId||`${x.table}|${x.played}`}`,x])).values()]}
function v3renderRating(){let root=document.getElementById('viewContent'),date=document.getElementById('dateFilter').value,players=v3filteredPlayers(v3playerRows(date)),rolling=v3rollingRows(date),byId=new Map();for(let x of players){let k=String(x.playerId||x.player);if(!byId.has(k))byId.set(k,{id:k,name:x.player,records:[],areas:new Set(),pits:new Set(),tables:new Set(),wl:0,totalIn:0,chipsOut:0,avgSum:0,avgN:0});let g=byId.get(k);g.records.push(x);g.areas.add(x.area);g.pits.add(v3pitLabel(x.pit));g.tables.add(x.table);g.wl+=Number(x.wl||0);g.totalIn+=Number(x.totalIn||x.buy||0);g.chipsOut+=Number(x.chipsOut||0);if(Number(x.avg)){g.avgSum+=Number(x.avg);g.avgN++}}let list=[...byId.values()].map(g=>{let m=rolling.filter(x=>String(x.playerId)===g.id&&x.area==='DVIP'),r=m.reduce((s,x)=>s+x.rolling,0),c=m.reduce((s,x)=>s+x.commission,0),rate=r?m.reduce((s,x)=>s+x.rolling*x.commissionRate,0)/r:0;return {...g,avg:g.avgN?g.avgSum/g.avgN:0,dvipRolling:r,dvipCommission:c,dvipRate:rate,area:[...g.areas].join(', ')}});if(v3RatingMode==='win')list=list.filter(x=>x.wl>0).sort((a,b)=>b.wl-a.wl).slice(0,10);else if(v3RatingMode==='loss')list=list.filter(x=>x.wl<0).sort((a,b)=>a.wl-b.wl).slice(0,10);else list.sort((a,b)=>b.wl-a.wl);root.innerHTML=`<div class="v3tabs"><button class="${v3RatingMode==='win'?'on':''}" onclick="v3setRatingMode('win')">↗ Top 10 Win (${Math.min(10,players.filter(x=>x.wl>0).length)})</button><button class="${v3RatingMode==='loss'?'on':''}" onclick="v3setRatingMode('loss')">↘ Top 10 Loss (${Math.min(10,players.filter(x=>x.wl<0).length)})</button><button class="${v3RatingMode==='all'?'on':''}" onclick="v3setRatingMode('all')">Tất cả khách (${new Set(players.map(x=>x.playerId||x.player)).size})</button><span class="v3grow"></span><small>${list.length} khách · Gaming Date ${date||'—'}</small></div><div class="v3tablewrap"><table class="v3table v3ratingtable"><thead><tr><th>#</th><th>Player Name</th><th>Player ID</th><th class="num">Avg Bet</th><th class="num">Player Win/Loss</th><th>Area</th><th class="num">DVIP Rolling</th><th class="num">Commission %</th></tr></thead><tbody>${list.map((x,i)=>`<tr><td><b class="rank">${i+1}</b></td><td><button class="v3playerlink" onclick='v3showPlayerDetail(${JSON.stringify(x.id)})'>${v3esc(x.name)}</button></td><td class="tablecode">${v3esc(x.id)}</td><td class="num gold">${v3cash(x.avg)}</td><td class="num ${x.wl<0?'red':'green'}">${x.wl>0?'+':''}${v3cash(x.wl)}</td><td>${v3esc(x.area)}</td><td class="num">${x.dvipRolling?v3cash(x.dvipRolling):'—'}</td><td class="num">${x.dvipRolling?x.dvipRate.toFixed(2)+'%':'—'}</td></tr>`).join('')||'<tr><td colspan="8" class="v3empty">Không có khách trong khu vực này ở Gaming Date đã chọn.</td></tr>'}</tbody></table></div>`}
function v3showPlayerDetail(id){let date=document.getElementById('dateFilter').value,rows=v3playerRows(date).filter(x=>String(x.playerId)===String(id)),roll=v3rollingRows(date).filter(x=>String(x.playerId)===String(id)),name=rows[0]?.player||roll[0]?.player||id,wl=rows.reduce((s,x)=>s+Number(x.wl||0),0),inTotal=rows.reduce((s,x)=>s+Number(x.totalIn||x.buy||0),0),out=rows.reduce((s,x)=>s+Number(x.chipsOut||0),0),avgRows=rows.filter(x=>Number(x.avg)),avg=avgRows.length?avgRows.reduce((s,x)=>s+Number(x.avg),0)/avgRows.length:0,dr=roll.filter(x=>x.area==='DVIP').reduce((s,x)=>s+x.rolling,0),dc=roll.filter(x=>x.area==='DVIP').reduce((s,x)=>s+x.commission,0),pop=document.createElement('div');pop.className='v3modal';pop.innerHTML=`<div class="v3playerdetail"><button class="close" onclick="this.closest('.v3modal').remove()">✕</button><h2>${v3esc(name)} · ${v3esc(id)}</h2><p class="v3hint">Gaming Date ${date||'—'}</p><div class="v3detailcards"><article><small>Player Win/Loss</small><b class="${wl<0?'red':'green'}">${v3cash(wl)}</b></article><article><small>Avg Bet</small><b>${v3cash(avg)}</b></article><article><small>Total In</small><b>${v3cash(inTotal)}</b></article><article><small>Chips Out</small><b>${v3cash(out)}</b></article><article><small>DVIP Rolling</small><b>${v3cash(dr)}</b></article><article><small>DVIP Commission</small><b>${v3cash(dc)}</b></article></div><h3>Player Rating slips</h3><div class="v3tablewrap"><table class="v3table"><thead><tr><th>Gaming Date</th><th>Area</th><th>Pit</th><th>Table</th><th>Avg Bet</th><th>Total In</th><th>Chips Out</th><th>Player W/L</th><th>Time Played</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${x.date}</td><td>${v3esc(x.area)}</td><td>${v3pitLabel(x.pit)}</td><td>${v3esc(x.table)}</td><td>${v3cash(x.avg)}</td><td>${v3cash(x.totalIn||x.buy)}</td><td>${v3cash(x.chipsOut)}</td><td>${v3cash(x.wl)}</td><td>${v3esc(x.played||'—')}</td></tr>`).join('')||'<tr><td colspan="9" class="v3empty">Không có rating slip.</td></tr>'}</tbody></table></div><h3>MGM NN Chip Purchase</h3><div class="v3tablewrap"><table class="v3table"><thead><tr><th>Area</th><th>Pit</th><th>Program Type</th><th>Chip Purchase</th><th>Chip Exchange</th><th>Chip Return</th><th>Rolling</th><th>Commission</th></tr></thead><tbody>${roll.map(x=>`<tr><td>${v3esc(x.area)}</td><td>${x.pit?v3pitLabel(x.pit):'—'}</td><td>${v3esc(x.program)}</td><td>${v3cash(x.purchase)}</td><td>${v3cash(x.exchange)}</td><td>${v3cash(x.returned)}</td><td>${v3cash(x.rolling)}</td><td>${v3cash(x.commission)}</td></tr>`).join('')||'<tr><td colspan="8" class="v3empty">Không có giao dịch MGM cho khách này.</td></tr>'}</tbody></table></div></div>`;document.body.appendChild(pop)}
v3renderContent=function(){if(v3Page==='rating')v3renderRating();else v3renderContentBase()};
