const v3ratingStyles=document.createElement('style');v3ratingStyles.textContent='.v3ratingtable{min-width:920px}.v3playerlink{padding:0;border:0;background:none;color:#f0f4fb;font-weight:700;text-align:left;cursor:pointer}.v3playerlink:hover{color:#ffc331;text-decoration:underline}.v3detailcards{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:9px;margin:16px 0 22px}.v3detailcards article{display:flex;flex-direction:column;gap:7px;padding:12px;background:#0b1424;border:1px solid #263750;border-radius:9px}.v3detailcards small{color:#91a4c0}.v3playerdetail h3{margin:20px 0 10px}.v3logo{width:54px;height:54px;flex:0 0 54px;border-radius:50%;background:radial-gradient(circle at 35% 28%,#ffc24a,#ff9800 72%);box-shadow:0 5px 20px #ff9f0033}.v3logo svg{width:49px;height:49px}@media(max-width:600px){.v3playerdetail{padding:16px!important}}';document.head.appendChild(v3ratingStyles);
v3layout();requestAnimationFrame(()=>{let mark=document.querySelector('.v3logo');if(mark){mark.setAttribute('aria-label','SMART LIVE roulette wheel with five playing cards');mark.innerHTML=`<svg viewBox="0 0 64 64" aria-hidden="true"><circle cx="32" cy="32" r="27" fill="none" stroke="#08111f" stroke-width="2.6"/><circle cx="32" cy="32" r="22.5" fill="none" stroke="#08111f" stroke-width="1.2" stroke-dasharray="1.5 2.8"/><circle cx="32" cy="32" r="5" fill="#08111f"/><g stroke="#08111f" stroke-width="1.4" stroke-linejoin="round"><path d="M14 21 19 16l11 2-1 25-13-2z" fill="#fff3d1"/><path d="m22 16 7-3 11 4-3 25-13 1z" fill="#fff"/><path d="m30 14 7-1 10 7-7 23-12-3z" fill="#f3d8dc"/><path d="m38 16 7 2 7 10-13 17-10-7z" fill="#fff"/><path d="m45 20 6 5 2 12-17 10-7-9z" fill="#fff3d1"/></g><path d="m24 25 2-2 2 2-2 2zM34 23l2-2 2 2-2 2zM41 28l2-2 2 2-2 2z" fill="#bb2439"/><circle cx="27" cy="33" r="1.5" fill="#111827"/><path d="m38 34 1.8-1 1.8 1-1.8 3z" fill="#bb2439"/><path d="m47 34 1.5-1.2 1.5 1.2-1.5 2.5z" fill="#111827"/><path d="M32 5v5m0 44v5M5 32h5m44 0h5M13 13l4 4m30 30 4 4M51 13l-4 4M17 47l-4 4" stroke="#08111f" stroke-width="2" stroke-linecap="round"/></svg>`;let title=mark.parentElement.querySelector('strong');if(title)title.textContent='SMART LIVE OPERATION'}});
